void mpic_unmask_irq ( struct irq_data * d ) { unsigned int loops = 100000 ; struct mpic * mpic = mpic_from_irq_data ( d ) ; DBG ( "%p: %s: enable_irq: %d (src %d)\n" , mpic , mpic -> name , d -> irq , src ) ; mpic_irq_write ( src , MPIC_INFO ( IRQ_VECTOR_PRI ) , mpic_irq_read ( src , MPIC_INFO ( IRQ_VECTOR_PRI ) ) & ~ MPIC_VECPRI_MASK ) ; { if ( ! loops -- ) { printk ( KERN_ERR "%s: timeout on hwirq %u\n" , __func__ , src ) ; break ; } } mpic_irq_read ( src , MPIC_INFO ( IRQ_VECTOR_PRI ) ) & MPIC_VECPRI_MASK ; } 